// 本地静态图片

// 滑块组件


export default {
  name: "Login",
  components: {
    Plus,
    Sidentify,
  },
  data() {
    return {
      CalendarIcon: Calendar,
      forgetForm: {    // 忘记密码表单
        username: '',
        newPassword: '',
        confirmPassword: '',
        // loginDevice: LOGIN_DEVICE_ENUM.PC.value,
      },
      dialogForget: false, // 找回密码弹窗
      identifyCodes: "1234567890", //验证码的数字库
      identifyCode: "",  // 验证码组件传值
      gzh: gzh,
      zhuoda: zhuoda,
      loginQR: loginQR,
      wechatIcon: wechatIcon,
      aliIcon: aliIcon,
      douyinIcon: douyinIcon,
      qqIcon: qqIcon,
      weiboIcon: weiboIcon,
      feishuIcon: feishuIcon,
      googleIcon: googleIcon,
      loginForm: {
        loginName: '',
        password: '',
        captchaCode: '',
        // loginDevice: LOGIN_DEVICE_ENUM.PC.value,
      },
      rules: {
        username: [
          {min: 3, max: 8, message: '长度在 3 到 8 个字符'},
          {required: true, message: '请输入用户名', trigger: ['blur', 'change']}
        ],
        newPassword: [
          {
            pattern: /^(?![0-9]+$)(?![a-zA-Z]+$)[0-9A-Za-z]{6,20}$/,
            message: '密码由字母和数字组成，且长度在6-20位',
            trigger: 'blur'
          },
          {required: true, message: '请输入新密码', trigger: ['blur', 'change']}
        ],
        confirmPassword: [
          {
            pattern: /^(?![0-9]+$)(?![a-zA-Z]+$)[0-9A-Za-z]{6,20}$/,
            message: '密码由字母和数字组成，且长度在6-20位',
            trigger: 'blur'
          },
          {required: true, message: '请输入新密码', trigger: ['blur', 'change']}
        ],
        loginName: [
          {required: true, message: '请输入用户名', trigger: ['blur', 'change']}
        ],
        password: [
          {required: true, message: '请输入密码', trigger: ['blur', 'change']}
        ],
        captchaCode: [
          {required: true, message: '请输入验证码', trigger: ['blur', 'change']}
        ],
      },
    }
  },

  created() {
    this.refreshCode(); //初始化验证码
  },
  mounted() {
    // 验证码初始化
    this.identifyCode = '';
    this.makeCode(this.identifyCodes, 4);
    this.loginForm.loginName = ""
    this.loginForm.password = ""
    this.loginForm.captchaCode = ""
  },

  methods: {
    async forgetSubmit() {
      //   确认输入表单合法
      if (this.forgetForm.username === '') {
        this.$message.error('请输入用户名');
        return;
      } else if (this.forgetForm.newPassword === '') {
        this.$message.error('请输入新密码');
        return;

      } else if (this.forgetForm.confirmPassword === '') {
        this.$message.error('请输入新密码');
        return;
      } else if (this.forgetForm.newPassword !== this.forgetForm.confirmPassword) {
        this.$message.error('两次密码输入不一致!');
        return;
      }

      console.log('registerForm  ', this.forgetForm);

      // 确认 用户名是否存在
      axios.post('/api/forgetpassword', this.forgetForm)
          .then(response => {
            // 将响应数据赋值给 title
            console.log("忘记密码 ", response.data);
            if (response.data === "不存在该用户名！") {
              this.$message.error('不存在该用户名！');
              return
            } else {
              this.$message.success('密码更改成功,请牢记密码！');
              this.dialogForget = false
            }
          })


    },
    handleClose(done) {
      this.$confirm('确认关闭？')
          .then(_ => {
            done();
          })
          .catch(_ => {
          });
    },
    Forget() {
//      this.$router.push({path: '/forget'})

      // 提示不支持找回
      this.$message.info('该功能暂不可用！');
      // this.dialogForget = true
//       找回密码
      console.log('找回密码')

    },
    Register() {
      this.$router.push({path: '/register'})
    },
    QRlogin() {
      // 提示该方式登录不可用
      this.$message.info('该登录方式暂不可用！');
    },
    loginSubmit() {
      console.log('identifyCode', this.identifyCode)
      if (this.loginForm.loginName === '') {
        this.$message.error('请输入用户名');
        return;

      } else if (this.loginForm.password === '') {
        this.$message.error('请输入密码');
        return;

      } else if (this.loginForm.captchaCode === '') {
        this.$message.error('请输入验证码');
        return;

      } else if (this.loginForm.captchaCode !== this.identifyCode) {
        this.$message.error('验证码错误');
        this.refreshCode();
        return;
      }

      console.log('registerForm  ', this.loginForm);

      // axios.post 像后端传递 form 对象
      axios.post('/api/login', this.loginForm)
          .then(response => {
            // 将响应数据赋值给 title
            console.log("登录 ", response.data);
            const data = response.data;
            // 后端成功返回对象 {message, role, username}，失败返回字符串
            if (data && typeof data === 'object' && data.message === '登录成功！') {
              this.$message.success('登录成功！');
              const role = data.role || 'student';
              const username = data.username || this.loginForm.loginName;
              // 存储用户名称与角色，用于登录分流与权限控制
              localStorage.setItem("username", username);
              localStorage.setItem("role", role);
              // 登录自动分流：教师→首页（可使用课堂行为分析），学生→DeepTutor智能知识问答
              if (role === 'teacher') {
                this.$router.push({path: '/index'});
              } else {
                this.$router.push({path: '/deeptutor'});
              }
            } else {
              // 字符串错误信息（如“密码错误！”“用户名或密码错误！”）
              this.$message.error(typeof data === 'string' ? data : '用户名或密码错误！');
              return
            }
          })
          .catch(error => {
            console.log(error);
          });

    },
    //验证码----start
    randomNum(min, max) {
      return Math.floor(Math.random() * (max - min) + min);
    },
    refreshCode() {
      this.identifyCode = "";
      this.makeCode(this.identifyCodes, 4);
    },
    makeCode(o, l) {
      for (let i = 0; i < l; i++) {
        this.identifyCode += this.identifyCodes[
            this.randomNum(0, this.identifyCodes.length)
            ];
      }
      console.log("this.identifyCode:", this.identifyCode);
    },
    //验证码----end

  }
};
</script>
